const TODAY = new Date('2026-06-02');
const flags = [
  { name: 'new-checkout',      type: 'release', created: '2025-06-01', expiry: '2025-09-01', rollout: 100 },
  { name: 'pricing-engine-v2', type: 'release', created: '2026-01-10', expiry: '2026-04-10', rollout: 100 },
  { name: 'tax-module-v2',     type: 'release', created: '2026-02-01', expiry: '2026-05-01', rollout: 100 },
  { name: 'search-rerank',     type: 'release', created: '2026-05-20', expiry: '2026-07-20', rollout: 35  },
  { name: 'banner-experiment', type: 'release', created: '2026-04-01', expiry: '2026-05-15', rollout: 50  },
  { name: 'kill-payments',     type: 'ops',     created: '2024-01-01', expiry: null,         rollout: 0   },
  { name: 'eu-data-residency', type: 'permission', created: '2024-01-01', expiry: null,      rollout: 100 }
];

function daysBetween(a, b) {
  return Math.round((b - a) / 86400000);
}

const releaseFlags = flags.filter(f => f.type === 'release');
const pastExpiry = releaseFlags.filter(f => f.expiry && new Date(f.expiry) < TODAY);
const stuckAt100 = releaseFlags.filter(f => f.rollout === 100);
const deletable = releaseFlags.filter(f => (f.expiry && new Date(f.expiry) < TODAY) || f.rollout === 100);

const activeBooleans = releaseFlags.length;
const totalConfigs = 2 ** activeBooleans;
const tested = activeBooleans + 1;
const untested = totalConfigs - tested;

console.log('release flags: ' + releaseFlags.length);
console.log('past expiry: ' + pastExpiry.length + ' (' + pastExpiry.map(f => f.name).join(', ') + ')');
console.log('stuck at 100%: ' + stuckAt100.length + ' (' + stuckAt100.map(f => f.name).join(', ') + ')');
console.log('deletable now: ' + deletable.length);
const oldest = pastExpiry.reduce((m, f) => Math.max(m, daysBetween(new Date(f.expiry), TODAY)), 0);
console.log('most-overdue release flag: ' + oldest + ' days past expiry');
console.log('runtime configs (2^' + activeBooleans + '): ' + totalConfigs);
console.log('realistically tested: ' + tested);
console.log('untested configs: ' + untested);
